// Module: Runtime/Schemas/Registry
// Purpose: Official foxglove JSON Schema constants and registration.
// Schema content stored as base64-encoded strings — no runtime file I/O.

using System;
using System.Text;

namespace Unity.FoxgloveSDK.Schemas
{
    /// <summary>
    /// Official foxglove JSON Schema constants and registration.
    /// Source: foxglove-sdk main@b298c3d1649e6e5dfd77a53b12ab7c27f97c7aba
    /// First access decodes the embedded schema strings once; avoid first-touching this type from tight frame-critical code.
    /// Schema content stored as base64-encoded C# constants — no runtime file I/O.
    /// </summary>
    public static class FoxgloveSchemaDefinitions
    {
        /// <summary>Schema name for FrameTransform.</summary>
        public const string FrameTransformSchemaName = "foxglove.FrameTransform";
        /// <summary>Schema name for SceneUpdate.</summary>
        public const string SceneUpdateSchemaName = "foxglove.SceneUpdate";
        /// <summary>Schema name for CompressedImage.</summary>
        public const string CompressedImageSchemaName = "foxglove.CompressedImage";
        /// <summary>Schema name for Log.</summary>
        public const string LogSchemaName = "foxglove.Log";
        /// <summary>Schema name for PointCloud.</summary>
        public const string PointCloudSchemaName = "foxglove.PointCloud";
        /// <summary>Schema name for LaserScan.</summary>
        public const string LaserScanSchemaName = "foxglove.LaserScan";
        /// <summary>Schema name for CameraCalibration.</summary>
        public const string CameraCalibrationSchemaName = "foxglove.CameraCalibration";
        /// <summary>Schema name for Unity2Foxglove SystemInfo telemetry.</summary>
        public const string SystemInfoSchemaName = "unity2foxglove.SystemInfo";
        // RawImage is intentionally omitted from the JSON schema registry because
        // the SDK currently exposes it through the protobuf-only camera path.
        /// <summary>Encoding identifier for JSON Schema.</summary>
        public const string JsonSchemaEncoding = "jsonschema";

        /// <summary>FrameTransform.json sha256=9986de138717bfaf</summary>
        private const string FrameTransformSchemaB64 =
            "";

        /// <summary>SceneUpdate.json sha256=bc563208a8b4bb2e</summary>
        private const string SceneUpdateSchemaB64 =
            "";

        /// <summary>CompressedImage.json sha256=f240ea31d2f0454b</summary>
        private const string CompressedImageSchemaB64 =
            "";

        /// <summary>PointCloud.json sha256=24ef13b749540e9f</summary>
        private const string PointCloudSchemaB64 =
            "";

        /// <summary>LaserScan.json sha256=d70fa26d3e66bc05</summary>
        private const string LaserScanSchemaB64 =
            "";

        /// <summary>CameraCalibration.json sha256=635fba3e5014a961</summary>
        private const string CameraCalibrationSchemaB64 =
            "";

        /// <summary>Decoded FrameTransform JSON Schema text.</summary>
        public static readonly string FrameTransformSchema =
            Encoding.UTF8.GetString(Convert.FromBase64String(FrameTransformSchemaB64));

        /// <summary>Decoded SceneUpdate JSON Schema text.</summary>
        public static readonly string SceneUpdateSchema =
            Encoding.UTF8.GetString(Convert.FromBase64String(SceneUpdateSchemaB64));

        /// <summary>Decoded CompressedImage JSON Schema text.</summary>
        public static readonly string CompressedImageSchema =
            Encoding.UTF8.GetString(Convert.FromBase64String(CompressedImageSchemaB64));

        /// <summary>Decoded PointCloud JSON Schema text.</summary>
        public static readonly string PointCloudSchema =
            Encoding.UTF8.GetString(Convert.FromBase64String(PointCloudSchemaB64));

        /// <summary>Decoded LaserScan JSON Schema text.</summary>
        public static readonly string LaserScanSchema =
            Encoding.UTF8.GetString(Convert.FromBase64String(LaserScanSchemaB64));

        /// <summary>Decoded CameraCalibration JSON Schema text.</summary>
        public static readonly string CameraCalibrationSchema =
            Encoding.UTF8.GetString(Convert.FromBase64String(CameraCalibrationSchemaB64));

        /// <summary>Unity2Foxglove SystemInfo JSON Schema text.</summary>
        public const string SystemInfoSchema =
            "{" +
            "\"title\":\"unity2foxglove.SystemInfo\"," +
            "\"description\":\"Unity runtime and device telemetry published by Unity2Foxglove.\"," +
            "\"type\":\"object\"," +
            "\"properties\":{" +
            "\"timestamp\":{\"type\":\"object\",\"properties\":{\"sec\":{\"type\":\"integer\",\"minimum\":0},\"nsec\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":999999999}},\"required\":[\"sec\",\"nsec\"]}," +
            "\"frameTimeMs\":{\"type\":\"number\",\"minimum\":0}," +
            "\"fps\":{\"type\":\"number\",\"minimum\":0}," +
            "\"gcMemoryMB\":{\"type\":\"number\",\"minimum\":0}," +
            "\"monoUsedMemoryMB\":{\"type\":\"number\",\"minimum\":0}," +
            "\"totalAllocatedMemoryMB\":{\"type\":\"number\",\"minimum\":0}," +
            "\"totalReservedMemoryMB\":{\"type\":\"number\",\"minimum\":0}," +
            "\"systemMemorySizeMB\":{\"type\":\"integer\",\"minimum\":0}," +
            "\"processorCount\":{\"type\":\"integer\",\"minimum\":0}," +
            "\"processorType\":{\"type\":\"string\"}," +
            "\"graphicsDeviceName\":{\"type\":\"string\"}," +
            "\"graphicsMemorySizeMB\":{\"type\":\"integer\",\"minimum\":0}," +
            "\"platform\":{\"type\":\"string\"}," +
            "\"unityVersion\":{\"type\":\"string\"}" +
            "}," +
            "\"required\":[\"timestamp\",\"frameTimeMs\",\"fps\",\"gcMemoryMB\",\"monoUsedMemoryMB\",\"totalAllocatedMemoryMB\",\"totalReservedMemoryMB\",\"systemMemorySizeMB\",\"processorCount\",\"processorType\",\"graphicsDeviceName\",\"graphicsMemorySizeMB\",\"platform\",\"unityVersion\"]" +
            "}";

        /// <summary>Log.json sha256=291a4d507377c811</summary>
        private const string LogSchemaB64 =
            "";

        /// <summary>Decoded Log JSON Schema text.</summary>
        public static readonly string LogSchema =
            Encoding.UTF8.GetString(Convert.FromBase64String(LogSchemaB64));

        /// <summary>
        /// Register core foxglove schemas into a registry. Idempotent (overwrites on duplicate name).
        /// </summary>
        public static void RegisterCoreSchemas(ISchemaRegistry registry)
        {
            if (registry == null)
                throw new ArgumentNullException(nameof(registry));

            registry.Register(new SchemaEntry
            {
                Name = FrameTransformSchemaName,
                Encoding = JsonSchemaEncoding,
                Content = FrameTransformSchema
            });

            registry.Register(new SchemaEntry
            {
                Name = SceneUpdateSchemaName,
                Encoding = JsonSchemaEncoding,
                Content = SceneUpdateSchema
            });

            registry.Register(new SchemaEntry
            {
                Name = CompressedImageSchemaName,
                Encoding = JsonSchemaEncoding,
                Content = CompressedImageSchema
            });

            registry.Register(new SchemaEntry
            {
                Name = LogSchemaName,
                Encoding = JsonSchemaEncoding,
                Content = LogSchema
            });

            registry.Register(new SchemaEntry
            {
                Name = PointCloudSchemaName,
                Encoding = JsonSchemaEncoding,
                Content = PointCloudSchema
            });

            registry.Register(new SchemaEntry
            {
                Name = LaserScanSchemaName,
                Encoding = JsonSchemaEncoding,
                Content = LaserScanSchema
            });

            registry.Register(new SchemaEntry
            {
                Name = CameraCalibrationSchemaName,
                Encoding = JsonSchemaEncoding,
                Content = CameraCalibrationSchema
            });

            registry.Register(new SchemaEntry
            {
                Name = SystemInfoSchemaName,
                Encoding = JsonSchemaEncoding,
                Content = SystemInfoSchema
            });
        }
    }
}
